UNITS = [
 {"id": "PEDS-U404", "ch": 51, "n": 1, "title": "Congenital Haemolytic Anaemia — Classification", "sec": "Classification of congenital haemolytic anaemia · p241", "guide": "Congenital haemolytic anaemia is classified into three groups. Defects of red cell membrane → hereditary spherocytosis. Disorders of red cell metabolism → glucose-6-phosphate dehydrogenase (G6PD) deficiency. Haemoglobinopathies (defect in the globin chain of Hb) → sickle cell anaemia and thalassaemia.", "qs": ["PEDS-C51-001", "PEDS-C51-002", "PEDS-C51-003", "PEDS-C51-004", "PEDS-C51-005", "PEDS-C51-006", "PEDS-C51-007", "PEDS-C51-008"]},
 {"id": "PEDS-U405", "ch": 51, "n": 2, "title": "Hereditary Spherocytosis — Inheritance, Pathogenesis & Membrane Proteins", "sec": "Hereditary spherocytosis — pathogenesis · p241", "guide": "Hereditary spherocytosis has autosomal dominant inheritance. Pathogenesis: a normal discoid RBC with an RBC cytoskeletal protein defect becomes a spherical RBC → decreased deformability → entrapment in the splenic microcirculation → haemolysis → splenomegaly (characteristic). The membrane diagram labels ConA, Band 3 and Glycophorin A crossing the lipid bilayer, with the underlying skeleton of spectrin, ankyrin, actin and Band 4.1; Band 4.1 is annotated as the m/c defect and spectrin as the 2nd m/c and the most severe.", "qs": ["PEDS-C51-009", "PEDS-C51-010", "PEDS-C51-011", "PEDS-C51-012", "PEDS-C51-013", "PEDS-C51-014", "PEDS-C51-015", "PEDS-C51-016", "PEDS-C51-017", "PEDS-C51-018", "PEDS-C51-019", "PEDS-C51-020", "PEDS-C51-021", "PEDS-C51-022", "PEDS-C51-023", "PEDS-C51-024", "PEDS-C51-025"]},
 {"id": "PEDS-U406", "ch": 51, "n": 3, "title": "Hereditary Spherocytosis — Clinical Features", "sec": "Hereditary spherocytosis — clinical features · p241", "guide": "Clinical features: variable onset of anaemia and jaundice due to increased lysis of RBCs, with 50% presenting as neonatal jaundice; splenomegaly; positive family history; pigment gallstones from increased bilirubin production; and aplastic crisis as an acute presentation. Parvovirus B19 infection in a patient with hereditary spherocytosis → bone marrow dysfunction → pancytopenia.", "qs": ["PEDS-C51-026", "PEDS-C51-027", "PEDS-C51-028", "PEDS-C51-029", "PEDS-C51-030", "PEDS-C51-031", "PEDS-C51-032", "PEDS-C51-033", "PEDS-C51-034", "PEDS-C51-035", "PEDS-C51-036", "PEDS-C51-037", "PEDS-C51-038", "PEDS-C51-039", "PEDS-C51-040", "PEDS-C51-041"]},
 {"id": "PEDS-U407", "ch": 51, "n": 4, "title": "Hereditary Spherocytosis — Investigations", "sec": "Hereditary spherocytosis — investigations · p242", "guide": "1. Peripheral smear: lack of central pallor in spherocytes; a small surface area of the RBC is lost during the shape change → cellular dehydration → increased concentration of Hb inside the RBC → hyperchromia. 2. Red cell indices: increased MCHC (characteristic). 3. Screening tests: osmotic fragility is increased — increased permeability to Na+ in spherocytes → increased Na+/H2O transport into the RBC → increased swelling and lysis at a lower concentration of hypotonic saline; incubated osmotic fragility incubates the patient's blood at 37°C for 24 hours and improves the sensitivity of testing; osmotic fragility is also seen in other haemolytic disorders. 4. Confirmatory tests: flow cytometry showing decreased binding of eosin-5-maleimide (EMA) to proteins, and molecular testing for deletion of mutations in RBCs.", "qs": ["PEDS-C51-042", "PEDS-C51-043", "PEDS-C51-044", "PEDS-C51-045", "PEDS-C51-046", "PEDS-C51-047", "PEDS-C51-048", "PEDS-C51-049", "PEDS-C51-050", "PEDS-C51-051", "PEDS-C51-052", "PEDS-C51-053", "PEDS-C51-054", "PEDS-C51-055", "PEDS-C51-056", "PEDS-C51-057", "PEDS-C51-058", "PEDS-C51-059", "PEDS-C51-060", "PEDS-C51-061", "PEDS-C51-062"]},
 {"id": "PEDS-U408", "ch": 51, "n": 5, "title": "Hereditary Spherocytosis — Management & Consequences of Splenectomy", "sec": "Hereditary spherocytosis — management and splenectomy · p242–243", "guide": "Management: 1. Lifelong folic acid supplementation — because of megaloblastic erythropoiesis from chronic haemolysis; given to all children with chronic haemolytic anaemias. 2. Splenectomy — the best treatment modality; decreased lysis → increased lifespan of RBCs → decreased severity of anaemia; laparoscopic partial splenectomy is preferred; concomitant cholecystectomy if gallstones are present. Consequences of splenectomy: absence of splenic macrophages → risk of infection by encapsulated bacteria (especially if age < 6 years) — Streptococcus pneumoniae, Haemophilus influenzae type b and meningococcus. Precautions: surgery after 6 years of age, immunization, and penicillin for 2 years post surgery.", "qs": ["PEDS-C51-063", "PEDS-C51-064", "PEDS-C51-065", "PEDS-C51-066", "PEDS-C51-067", "PEDS-C51-068", "PEDS-C51-069", "PEDS-C51-070", "PEDS-C51-071", "PEDS-C51-072", "PEDS-C51-073", "PEDS-C51-074", "PEDS-C51-075", "PEDS-C51-076", "PEDS-C51-077", "PEDS-C51-078", "PEDS-C51-079", "PEDS-C51-080", "PEDS-C51-081"]},
 {"id": "PEDS-U409", "ch": 51, "n": 6, "title": "G6PD Deficiency — Epidemiology & Pathophysiology", "sec": "G6PD deficiency — epidemiology and pathophysiology · p243", "guide": "G6PD deficiency is the m/c RBC enzyme deficiency, X-linked recessive, and is commonly seen in Africans, Mediterraneans and Asians. Pathophysiology — the HMP shunt: glucose-6-phosphate is acted on by G6PD; NADP is converted to NADPH, which converts glutathione to reduced glutathione (via 6-phosphoglycerate), and reduced glutathione protects RBCs from oxidative stress. When G6PD is deficient the shunt is blocked → decreased levels of reduced glutathione → oxidative stress → haemolysis.", "qs": ["PEDS-C51-082", "PEDS-C51-083", "PEDS-C51-084", "PEDS-C51-085", "PEDS-C51-086", "PEDS-C51-087", "PEDS-C51-088", "PEDS-C51-089", "PEDS-C51-090", "PEDS-C51-091", "PEDS-C51-092", "PEDS-C51-093", "PEDS-C51-094", "PEDS-C51-095", "PEDS-C51-096"]},
 {"id": "PEDS-U410", "ch": 51, "n": 7, "title": "G6PD Deficiency — Clinical Features & Precipitants", "sec": "G6PD deficiency — clinical features and precipitants · p243", "guide": "Clinical features: variable onset — early presentation is neonatal jaundice, late presentation is episodic haemolysis. Risk factors for episodic haemolysis are fever, fava beans and drugs. Drug-induced haemolysis starts 2–3 days after exposure and is self-limiting; the drugs listed are primaquine, nitrofurantoin, sulfonamides, nalidixic acid and phenazopyridine.", "qs": ["PEDS-C51-097", "PEDS-C51-098", "PEDS-C51-099", "PEDS-C51-100", "PEDS-C51-101", "PEDS-C51-102", "PEDS-C51-103", "PEDS-C51-104", "PEDS-C51-105", "PEDS-C51-106", "PEDS-C51-107", "PEDS-C51-108", "PEDS-C51-109", "PEDS-C51-110", "PEDS-C51-111", "PEDS-C51-112", "PEDS-C51-113"]},
 {"id": "PEDS-U411", "ch": 51, "n": 8, "title": "G6PD Deficiency — Investigations & Management", "sec": "G6PD deficiency — investigations and management · p243–244", "guide": "Investigations: 1. Peripheral smear — Heinz bodies: oxidative stress converts Hb to methaemoglobin → condensation → Heinz bodies; the Heinz bodies are engulfed by splenic macrophages, producing bite cells. 2. Enzyme assay in RBCs is the confirmatory test, showing decreased enzyme levels in RBCs. Management is supportive: most episodes are self-limiting, and implicated drugs must be avoided.", "qs": ["PEDS-C51-114", "PEDS-C51-115", "PEDS-C51-116", "PEDS-C51-117", "PEDS-C51-118", "PEDS-C51-119", "PEDS-C51-120", "PEDS-C51-121", "PEDS-C51-122", "PEDS-C51-123", "PEDS-C51-124", "PEDS-C51-125", "PEDS-C51-126", "PEDS-C51-127", "PEDS-C51-128"]},
 {"id": "PEDS-U412", "ch": 51, "n": 9, "title": "Sickle Cell Anaemia — Genetics & Pathogenesis", "sec": "Sickle cell anaemia — genetics and pathogenesis · p244", "guide": "Sickle cell anaemia is autosomal recessive with a high incidence in the tribal populations of Madhya Pradesh and Maharashtra. Pathogenesis: a mutation in the gene for the β-globin chain of haemoglobin → glutamate is replaced by valine at the 6th position → production of defective Hb, HbS (normal Hb is HbA). The RBC with HbS sickles under hypoxia, dehydration, fever and metabolic acidosis; repeated sickling makes RBCs fragile → haemolysis, while sickle cells blocking blood flow cause ischaemia → infarction.", "qs": ["PEDS-C51-129", "PEDS-C51-130", "PEDS-C51-131", "PEDS-C51-132", "PEDS-C51-133", "PEDS-C51-134", "PEDS-C51-135", "PEDS-C51-136", "PEDS-C51-137", "PEDS-C51-138", "PEDS-C51-139", "PEDS-C51-140", "PEDS-C51-141", "PEDS-C51-142", "PEDS-C51-143"]},
 {"id": "PEDS-U413", "ch": 51, "n": 10, "title": "Sickle Cell Anaemia — Clinical Features & Crises", "sec": "Sickle cell anaemia — clinical features · p244–245", "guide": "Sickle cell anaemia manifests after 6 months of age because HbF predominates for the first 6 months and is protective. Features: icterus, pallor, vaso-occlusive crisis with painful episodes (characteristic), dactylitis/hand-and-foot syndrome (swelling of fingers and toes, manifesting in infancy), acute chest syndrome (fever and breathing difficulty resembling pneumonia with new-onset infiltrates on chest X-ray) and stroke episodes. Sickling of cells in the spleen: repeated infarcts → autosplenectomy by 6 years of age (functional hyposplenism) → recurrent infection by encapsulated bacteria; venous blockade → acute pooling of blood → ≥ 2% Hb reduction → pallor and shock. Aplastic crisis is pancytopenia precipitated by parvovirus B19 infection.", "qs": ["PEDS-C51-144", "PEDS-C51-145", "PEDS-C51-146", "PEDS-C51-147", "PEDS-C51-148", "PEDS-C51-149", "PEDS-C51-150", "PEDS-C51-151", "PEDS-C51-152", "PEDS-C51-153", "PEDS-C51-154", "PEDS-C51-155", "PEDS-C51-156", "PEDS-C51-157", "PEDS-C51-158", "PEDS-C51-159", "PEDS-C51-160", "PEDS-C51-161", "PEDS-C51-162", "PEDS-C51-163", "PEDS-C51-164", "PEDS-C51-165"]},
 {"id": "PEDS-U414", "ch": 51, "n": 11, "title": "Sickle Cell Anaemia — Investigations & Sickle Cell Trait", "sec": "Sickle cell anaemia — investigations and trait · p245", "guide": "Investigations: 1. Peripheral smear — sickled RBCs. 2. Screening test — the sickling test, inducing sickling by adding 2% sodium metabisulphite. 3. Hb electrophoresis — the initial, best diagnostic test. 4. High-performance liquid chromatography (HPLC) — the gold standard test, which detects and quantifies HbS. Note: in sickle cell trait, HbA + HbS are present, giving less severe manifestations.", "qs": ["PEDS-C51-166", "PEDS-C51-167", "PEDS-C51-168", "PEDS-C51-169", "PEDS-C51-170", "PEDS-C51-171", "PEDS-C51-172", "PEDS-C51-173", "PEDS-C51-174", "PEDS-C51-175", "PEDS-C51-176", "PEDS-C51-177", "PEDS-C51-178", "PEDS-C51-179"]},
 {"id": "PEDS-U415", "ch": 51, "n": 12, "title": "Sickle Cell Anaemia — Management & Preventive Care", "sec": "Sickle cell anaemia — management and preventive care · p245", "guide": "Management: good hydration; analgesics for pain episodes; PRBC transfusion for aplastic and sequestration crises (to increase the oxygen carrying capacity of blood); exchange transfusion for acute chest syndrome and stroke — sequential removal of HbS from the circulation with the goal of HbS concentration < 30% of Hb; haematopoietic stem cell transplant is curative; newer agents reduce vaso-occlusive episodes — crizanlizumab, a monoclonal antibody against P-selectin that decreases attachment of sickled RBCs to the vessel wall, and voxelotor, which decreases HbS polymerization and hence sickling. Preventive care: penicillin prophylaxis from infancy to 5 years of age; immunization against encapsulated organisms; hydroxyurea to increase HbF production and thereby decrease sickling episodes, started after 9 months of age.", "qs": ["PEDS-C51-180", "PEDS-C51-181", "PEDS-C51-182", "PEDS-C51-183", "PEDS-C51-184", "PEDS-C51-185", "PEDS-C51-186", "PEDS-C51-187", "PEDS-C51-188", "PEDS-C51-189", "PEDS-C51-190", "PEDS-C51-191", "PEDS-C51-192", "PEDS-C51-193", "PEDS-C51-194", "PEDS-C51-195", "PEDS-C51-196", "PEDS-C51-197", "PEDS-C51-198"]},
 {"id": "PEDS-U416", "ch": 51, "n": 13, "title": "β-Thalassaemia — Inheritance & Genotype Table", "sec": "β-thalassaemia — inheritance and types · p246", "guide": "β-thalassaemia is autosomal recessive. Types arise from reduction or absence of β-globin chain synthesis; normally 2 alleles code for the β-globin chain. Key: β = normal, β+ = decreased production, β0 = no production. Genotype table — β/β normal; β/β+ β-thalassaemia trait (mild), asymptomatic; β+/β+ or β+/β0 β-thalassaemia intermedia, mild to moderate severity (β+/β0 more severe than β+/β+); β0/β0 β-thalassaemia major or Cooley's anaemia, the most severe form, needing transfusion every 3–4 weeks.", "qs": ["PEDS-C51-199", "PEDS-C51-200", "PEDS-C51-201", "PEDS-C51-202", "PEDS-C51-203", "PEDS-C51-204", "PEDS-C51-205", "PEDS-C51-206", "PEDS-C51-207", "PEDS-C51-208", "PEDS-C51-209", "PEDS-C51-210", "PEDS-C51-211", "PEDS-C51-212", "PEDS-C51-213"]},
 {"id": "PEDS-U417", "ch": 51, "n": 14, "title": "β-Thalassaemia — Pathophysiology & Clinical Features", "sec": "β-thalassaemia — pathophysiology and clinical features · p246", "guide": "Absent β-globin chain synthesis → accumulation of α-chains in RBCs → instability of cells → early destruction → ineffective erythropoiesis. This produces severe anaemia (transfusion dependent) and extramedullary haematopoiesis — hepatosplenomegaly and expansion in the skull. Thalassemic facies comprises frontal bossing, depressed nasal bridge, maxillary prominence and dental malocclusion; the skull X-ray shows prominent vertical trabeculae — the hair-on-end appearance. Note: α and β chains are normally produced in a 1:1 ratio.", "qs": ["PEDS-C51-214", "PEDS-C51-215", "PEDS-C51-216", "PEDS-C51-217", "PEDS-C51-218", "PEDS-C51-219", "PEDS-C51-220", "PEDS-C51-221", "PEDS-C51-222", "PEDS-C51-223", "PEDS-C51-224", "PEDS-C51-225", "PEDS-C51-226", "PEDS-C51-227", "PEDS-C51-228", "PEDS-C51-229", "PEDS-C51-230"]},
 {"id": "PEDS-U418", "ch": 51, "n": 15, "title": "β-Thalassaemia — Investigations & Management", "sec": "β-thalassaemia — investigations and management · p247", "guide": "Investigations: 1. Peripheral smear — nucleated RBCs and microcytic hypochromic RBCs with central pallor > 1/3. 2. Haemoglobin electrophoresis — the initial diagnostic test. 3. HPLC — the gold standard test. Management: supportive — blood transfusion every 3–4 weeks using leukocyte-depleted/irradiated blood products (to reduce the risk of allergic reactions), with a pre-transfusion target Hb of 9–10 g/dL to reduce deformities and promote growth. Curative treatment is haematopoietic stem cell transplant.", "qs": ["PEDS-C51-231", "PEDS-C51-232", "PEDS-C51-233", "PEDS-C51-234", "PEDS-C51-235", "PEDS-C51-236", "PEDS-C51-237", "PEDS-C51-238", "PEDS-C51-239", "PEDS-C51-240", "PEDS-C51-241", "PEDS-C51-242", "PEDS-C51-243", "PEDS-C51-244", "PEDS-C51-245"]},
 {"id": "PEDS-U419", "ch": 51, "n": 16, "title": "β-Thalassaemia — Iron Overload & Chelation", "sec": "β-thalassaemia — complication of iron overload · p247", "guide": "Iron overload complicates repeated transfusions (monitor after over 1 year of transfusion) and is the major cause of morbidity and mortality through cardiotoxicity. Organs damaged: liver, spleen and heart. High transferrin saturation decreases the bacteriostatic properties of lactoferrin → increased risk of infection, most commonly Yersinia enterocolitica. Investigations: serum ferritin > 1000 pg/L, and MRI — R2 or R2* weighted liver MRI (best) and T2-weighted cardiac MRI. Management: iron chelators — deferasirox (oral) is preferred and causes only mild GI disturbances; deferoxamine (s.c.) causes ototoxicity and retinal toxicity; deferiprone (oral) causes neutropenia and cartilage damage.", "qs": ["PEDS-C51-246", "PEDS-C51-247", "PEDS-C51-248", "PEDS-C51-249", "PEDS-C51-250", "PEDS-C51-251", "PEDS-C51-252", "PEDS-C51-253", "PEDS-C51-254", "PEDS-C51-255", "PEDS-C51-256", "PEDS-C51-257", "PEDS-C51-258", "PEDS-C51-259", "PEDS-C51-260", "PEDS-C51-261", "PEDS-C51-262", "PEDS-C51-263", "PEDS-C51-264", "PEDS-C51-265", "PEDS-C51-266"]},
]

