 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "The sickling test induces sickling by adding 2% sodium ___.", "opts": ["Metabisulphite", "Citrate", "Nitroprusside", "Dithionite-free saline"], "ans": 0, "exp": "Sickling test: induction of sickling by adding 2% sodium metabisulphite. (Book p245)", "type": "fill", "id": "PEDS-C51-168"},
