 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "Hb electrophoresis in sickle cell anaemia is described as the —", "opts": ["Confirmatory enzyme assay", "Gold standard test", "Initial, best diagnostic test", "Screening test"], "ans": 2, "exp": "Hb electrophoresis: initial, best diagnostic test. (Book p245)", "type": "mcq", "id": "PEDS-C51-170"},
