 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "Compared with sickle cell anaemia, the manifestations of sickle cell trait are —", "opts": ["More severe", "Identical", "Less severe", "Confined to the neonatal period"], "ans": 2, "exp": "Sickle cell trait: HbA + HbS → less severe manifestations. (Book p245)", "type": "mcq", "id": "PEDS-C51-174"},
 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "Match each investigation for sickle cell anaemia with its stated role:", "opts": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-2, B-1, C-4, D-3", "A-3, B-4, C-1, D-2"], "ans": 3, "exp": "Smear → screening → electrophoresis → HPLC is the diagnostic ladder given. Correct pairs: Peripheral smear→Shows sickled RBCs; Sickling test→Screening test using 2% sodium metabisulphite; Hb electrophoresis→Initial, best diagnostic test; HPLC→Gold standard that quantifies HbS. (Book p245)", "type": "match", "pairs": [["Peripheral smear", "Initial, best diagnostic test"], ["Sickling test", "Gold standard that quantifies HbS"], ["Hb electrophoresis", "Shows sickled RBCs"], ["HPLC", "Screening test using 2% sodium metabisulphite"]], "id": "PEDS-C51-175"},
 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "True or False — HPLC is preferred over Hb electrophoresis as the gold standard because it quantifies HbS.", "opts": ["True", "False"], "ans": 0, "exp": "True — HPLC is the gold standard and detects and quantifies HbS. (Book p245)", "type": "tf", "id": "PEDS-C51-176"},
 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "True or False — The sickling test is regarded as the gold standard for diagnosing sickle cell anaemia.", "opts": ["True", "False"], "ans": 1, "exp": "False — the sickling test is a screening test; HPLC is the gold standard. (Book p245)", "type": "tf", "id": "PEDS-C51-177"},
 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "Odd one out (tests used in sickle cell anaemia):", "opts": ["Hb electrophoresis", "HPLC", "Osmotic fragility test", "Sickling test with sodium metabisulphite"], "ans": 2, "exp": "Osmotic fragility belongs to hereditary spherocytosis. (Book p242–245)", "type": "odd", "id": "PEDS-C51-178"},
 {"sec": "Sickle cell anaemia — investigations and trait · p245", "page": 245, "q": "The correct interpretation is —", "opts": ["β-thalassaemia trait", "G6PD deficiency", "Sickle cell anaemia", "Sickle cell trait"], "ans": 3, "exp": "HbA + HbS = sickle cell trait, which has less severe manifestations. (Book p245)", "type": "case", "stem": "A 12-year-old, asymptomatic, is found to have a positive sickling test during a screening camp; HPLC shows both HbA and HbS.", "id": "PEDS-C51-179"},
