 {"sec": "Sickle cell anaemia — management and preventive care · p245", "page": 245, "q": "Match each sickle cell therapy with its mechanism or indication:", "opts": ["A-4, B-1, C-3, D-2", "A-3, B-2, C-1, D-4", "A-4, B-1, C-2, D-3", "A-1, B-4, C-2, D-3"], "ans": 2, "exp": "Each agent acts at a different point in the sickling/vaso-occlusion cascade. Correct pairs: Exchange transfusion→Acute chest syndrome and stroke; Crizanlizumab→Monoclonal antibody against P-selectin; Voxelotor→Reduces HbS polymerization; Hydroxyurea→Increases HbF production. (Book p245)", "type": "match", "pairs": [["Exchange transfusion", "Monoclonal antibody against P-selectin"], ["Crizanlizumab", "Reduces HbS polymerization"], ["Voxelotor", "Increases HbF production"], ["Hydroxyurea", "Acute chest syndrome and stroke"]], "id": "PEDS-C51-194"},
 {"sec": "Sickle cell anaemia — management and preventive care · p245", "page": 245, "q": "True or False — The target of exchange transfusion in acute chest syndrome is to keep HbS below 30% of total haemoglobin.", "opts": ["True", "False"], "ans": 0, "exp": "True — goal: HbS concentration < 30% of Hb. (Book p245)", "type": "tf", "id": "PEDS-C51-195"},
 {"sec": "Sickle cell anaemia — management and preventive care · p245", "page": 245, "q": "True or False — Hydroxyurea is described in the chapter as curative for sickle cell anaemia.", "opts": ["True", "False"], "ans": 1, "exp": "False — haematopoietic stem cell transplant is curative; hydroxyurea only reduces sickling episodes. (Book p245)", "type": "tf", "id": "PEDS-C51-196"},
 {"sec": "Sickle cell anaemia — management and preventive care · p245", "page": 245, "q": "Odd one out (elements of preventive care in sickle cell anaemia):", "opts": ["Hydroxyurea after 9 months of age", "Iron supplementation from infancy", "Penicillin prophylaxis to 5 years", "Immunization against encapsulated organisms"], "ans": 1, "exp": "Iron supplementation is not part of sickle cell preventive care; the other three are listed. (Book p245)", "type": "odd", "id": "PEDS-C51-197"},
 {"sec": "Sickle cell anaemia — management and preventive care · p245", "page": 245, "q": "Which agent would be added to raise HbF and reduce the frequency of episodes?", "opts": ["Crizanlizumab", "Voxelotor", "Hydroxyurea", "Deferasirox"], "ans": 2, "exp": "Hydroxyurea increases HbF production, thereby decreasing sickling episodes. (Book p245)", "type": "case", "stem": "A 10-year-old with sickle cell anaemia has frequent painful crises despite good hydration and analgesia.", "id": "PEDS-C51-198"},
